"""Generate notebook SHORT guides from public main/supplement aggregate records.

No notebook execution, data retrieval, table creation, or patient-row access.
Templates describe the current code; numerical summaries share report inputs.
"""
from pathlib import Path
import json

from render_current_report import SOFA_TIMING_NOTE, estimate, pvalue
from report_survival_supplement import load_public, interval, probability

PREFIX = "mimic-iv-portfolio.copd_raas."
REPORT = "https://makotoy56.github.io/mimic-iv-copd-raas-analysis/copd_raas_survival_report.html#supplementary-sensitivity-analyses"
MAIN_INPUT = [f"`{PREFIX}cohort_copd_outcomes_extended`", f"`{PREFIX}cohort_copd_raas_detailed` (joined by the shared loader)"]
PREREQUISITES = "Run `sql/04_build_outcomes.sql` and then `sql/04_build_outcomes_extended.sql` after phase 03 and before any 04-series notebook. Those SQL scripts create the outcome tables; the 04-series notebooks do not. See [the dependency map](METHODS_OVERVIEW.md#outcome-table-dependencies)."
REFRESH_OUTPUT = ["No new persistent BigQuery table.", "Shared `refresh()` recomputes all main model specifications, four figures, `docs/CURRENT_ANALYSIS.json`, and the optional secondary logistic exports under ignored `python/outputs/`.", "Report source and narrative are regenerated when their provenance checks pass. Revalidate/rebind supplementary results after changing the main reference; build final HTML with `scripts/build_report.py`."]
MODES = 'The source notebook defaults to `DATA_MODE = "synthetic"`; those outputs are artificial demonstrations. `current` explicitly uses the approved, US-dry-run/200-MB-capped loader; patient/admission/stay keys remain in memory. `local` reads a saved, hash-verified aggregate result without another query. Never display admission-level rows.'
SUPP_OUTPUT = ["Aggregate tables and figures in the notebook; no BigQuery table or main estimate is overwritten.", "The explicit CLI `--output` option saves aggregate JSON and figures under ignored `reports/local_supplements/`. Tracked notebook outputs remain stripped.", "Selected clinical aggregates are published separately in [the results record](SURVIVAL_SENSITIVITY_RESULTS.json) and [Quarto](" + REPORT + ")."]


def note(title, notebook, objective, inputs, outputs, methods, results, next_step, related=""):
    parts = ["<!-- Generated by scripts/render_short_notes.py; edit its templates rather than this file. -->", "",
             f"# {title} (SHORT)", "", f"[Full notebook](../notebooks/{notebook}.ipynb)", "",
             "## Objective", "", objective, "", "## Input", ""]
    parts += ["- " + item for item in inputs]
    parts += ["", "## Output and downstream use", ""] + ["- " + item for item in outputs]
    parts += ["", "## Key methods and scope", ""] + ["- " + item for item in methods]
    if results:
        parts += ["", "## Results summary", "", results]
    if related:
        parts += ["", "## Related analyses", "", related]
    parts += ["", "## Next step", "", next_step, ""]
    return "\n".join(parts)


def generate(repo):
    main = json.loads((repo / "docs/CURRENT_ANALYSIS.json").read_text())
    supplement = load_public(repo)  # Reject stale clinical publication inputs.
    if supplement is None and any((repo / "notebooks").glob("05*.ipynb")):
        raise ValueError("Supplement aggregate record required for 05-series SHORT guides")
    models = main["models"]
    notes = {}
    def add(stem, *args, **kwargs):
        notes[stem + "_SHORT.md"] = note(*args, notebook=stem, **kwargs)
    def table_inputs(*names):
        return [f"`{PREFIX}{name}`" for name in names]
    def next_to(stem, label):
        return f"Next: [{label}]({stem}_SHORT.md)."

    add("01_icu_cohort", "01 — Adult ICU cohort extraction",
        objective="Build the adult ICU cohort, anchored to the first ICU stay within each hospital admission. A patient can contribute multiple admissions.",
        inputs=["MIMIC-IV v3.1 `icustays`, `patients`, and `admissions` in BigQuery."],
        outputs=table_inputs("cohort_icu") + ["Input to COPD diagnosis selection in phase 02."],
        methods=["Executes `sql/01_extract_base.sql`, which creates or replaces the cohort table.",
                 "Uses estimated hospital-admission age `anchor_age + admission_year - anchor_year >= 18`; preserves raw `anchor_age` and `age_anchor_topcoded`.",
                 "Keeps the first ICU stay per patient and hospital admission, not the first admission in a patient's life.",
                 "Age is approximate; anchor age 91 represents the aggregated oldest group. ICU LOS uses continuous elapsed days.",
                 "The notebook loads rows for schema checking and prints `info()` and shape; it does not display row previews or prove all downstream content QA."],
        results="", next_step=next_to("02_cohort_and_exposures", "02 — COPD cohort and prescription orders"))

    add("02_cohort_and_exposures", "02 — COPD cohort and prescription orders",
        objective="Select COPD admissions and build binary and class-specific pre-ICU prescription-order indicators.",
        inputs=table_inputs("cohort_icu") + ["MIMIC-IV v3.1 `diagnoses_icd` and `prescriptions`."],
        outputs=table_inputs("cohort_copd", "cohort_copd_raas", "cohort_copd_raas_detailed"),
        methods=["Executes the three corresponding `02_*.sql` scripts; COPD selection uses the existing ICD-9/10 diagnosis-code rules.",
                 "Qualifying inpatient prescription records must be in the same admission and have `starttime <= intime`, including equality.",
                 "Binary and ACEi-only/ARB-only/both/neither flags describe qualifying orders, not verified administration, adherence, or simultaneous treatment.",
                 "Neither means no qualifying order under this definition; it does not prove absence of all medication use.",
                 "Displays aggregate exposure counts and compares total rows with distinct ICU stays."],
        results="", next_step=next_to("03a_baseline", "03a — Cohort descriptors"))

    add("03a_baseline", "03a — Cohort descriptors and binary exposure",
        objective="Assemble demographic and hospital descriptors with the existing admission-age estimate and binary prescription-order flag.",
        inputs=table_inputs("cohort_copd", "cohort_copd_raas") + ["MIMIC-IV patient and hospital-admission tables."],
        outputs=table_inputs("cohort_copd_baseline") + ["Feeds `sql/04_build_outcomes.sql`; this step does not add first-day SOFA."],
        methods=["Executes `sql/03_build_baseline.sql` and preserves admission age plus raw/topcoded-age fields.",
                 "Adds sex, anchor year/group and continuous hospital LOS; joins binary exposure by patient/admission/stay keys.",
                 "A missing qualifying exposure row is coded 0. This means no qualifying record, not proven non-use.",
                 "Patient `dod` is retained, but hospital `admissions.deathtime` is the later in-hospital endpoint source.",
                 "Prints schema/shape, aggregate age descriptors and exposure counts; does not display patient rows.", PREREQUISITES],
        results="", next_step=next_to("03b_merge_exposures", "03b — Detailed exposure merge"))

    add("03b_merge_exposures", "03b — Detailed prescription-order merge",
        objective="Merge detailed qualifying order flags and check their aggregate distributions.",
        inputs=table_inputs("cohort_copd", "cohort_copd_raas_detailed"),
        outputs=table_inputs("cohort_copd_with_raas") + ["Supports merge/distribution checks. The shared model loader instead reads extended outcomes and joins detailed exposure directly."],
        methods=["Executes `sql/03_merge_exposures.sql` using patient/admission/stay join keys.",
                 "Both-class flags and legacy `is_monotherapy` labels describe order categories; they do not establish concurrent treatment or actual administration.",
                 "Checks before/after row counts, missing exposure fields, exposure-group distributions, and aggregate flag totals.", PREREQUISITES],
        results="", next_step=next_to("04a_outcomes_and_modeling", "04a — Primary survival analysis"))

    primary = models["primary_refined"]["estimates"]["raas_pre_icu"]
    add("04a_outcomes_and_modeling", "04a — Primary ICU-COPD survival analysis",
        objective="Assess qualifying pre-ICU RAAS prescription orders and in-hospital mortality from ICU entry.",
        inputs=MAIN_INPUT, outputs=REFRESH_OUTPUT,
        methods=[PREREQUISITES,
                 "Calls shared `refresh()` and displays refined primary estimates and rank PH p-values. It reads prebuilt outcome tables; it does not build outcomes in BigQuery.",
                 "Uses continuous elapsed follow-up to recorded in-hospital death; discharge time is a flagged fallback only when death time is missing. Live discharge is censored in this cause-specific analysis.",
                 "The refined primary Cox model adjusts for age and sex, stratifies by `anchor_year_group`, and uses ordinary model-based intervals without SOFA or patient clustering.",
                 "Shared calculations also fit Kaplan-Meier/log-rank and rank Schoenfeld-based PH diagnostics. Four main figures are refreshed together."],
        results=f"The saved main cohort has {main['n']:,} admissions and {main['deaths']:,} deaths. The refined primary estimate is HR {primary['hr']:.3f} (95% CI {interval(primary)}); p={pvalue(primary['p'])}. These are observational associations. Numerical source: [CURRENT_ANALYSIS.json](CURRENT_ANALYSIS.json).",
        related="[05a](05a_patient_cluster_sensitivity_SHORT.md) separately evaluates patient-cluster inference; [05b](05b_competing_risks_SHORT.md) reports death/discharge cumulative incidence. These preserve the original main estimates.",
        next_step=next_to("04b_outcomes_and_modeling_raas_subgroups", "04b — Subclasses versus neither"))

    sub = models["subgroups"]
    e1, e2 = [sub["estimates"][k] for k in ["acei_pre_icu", "arb_pre_icu"]]
    add("04b_outcomes_and_modeling_raas_subgroups", "04b — ACEi-only and ARB-only orders versus neither",
        objective="Estimate each prescription-order class association against the shared neither-order reference.",
        inputs=MAIN_INPUT, outputs=REFRESH_OUTPUT,
        methods=[PREREQUISITES,
                 "Calls shared `refresh()` and displays subgroup estimates and PH p-values; it is not an isolated subgroup-only refresh.",
                 "Excludes records with both class flags positive. Fits ACEi and ARB indicators together with age and sex, stratified by era, using ordinary model-based inference.",
                 "Each class is compared with neither qualifying order. The main results contain no direct ACEi-versus-ARB test; differing p-values do not establish a class difference.",
                 "Uses the original ICU-entry endpoint/fallback definition and live-discharge censoring. Order flags do not establish actual or simultaneous administration."],
        results=f"The saved subclass model includes {sub['n']:,} admissions and {sub['deaths']:,} deaths. ACEi-only versus neither: HR {e1['hr']:.3f} (95% CI {interval(e1)}); p={pvalue(e1['p'])}. ARB-only versus neither: HR {e2['hr']:.3f} (95% CI {interval(e2)}); p={pvalue(e2['p'])}. Source: [CURRENT_ANALYSIS.json](CURRENT_ANALYSIS.json).",
        related="The published [05a–05c supplements](SURVIVAL_SENSITIVITY_SUPPLEMENTS.md) use the binary RAAS grouping, not new class-specific or direct ACEi/ARB analyses. The separate [local contrast workflow](ACEI_ARB_SUPPLEMENT_LOCAL.md) remains outside the public main results.",
        next_step=next_to("04c_extended_covariate_cox_model", "04c — Exploratory extended models"))

    rows = ["| Specification | RAAS HR (95% CI) | p |", "| --- | --- | ---: |"]
    for key, label in [("core", "Unpenalized core"), ("core_penalized", "Core + L2 (0.1)"), ("icu_pooled", "Pooled ICU"), ("icu_pooled_penalized", "Pooled ICU + L2 (0.01)"), ("core_ph_stratified", "CHF/SOFA strata"), ("icu_ph_stratified", "CHF/SOFA/ICU strata")]:
        e = models[key]["estimates"]["raas_pre_icu"]
        rows.append(f"| {label} | {estimate(e)} | {pvalue(e['p'])} |")
    add("04c_extended_covariate_cox_model", "04c — Exploratory extended Cox models",
        objective=SOFA_TIMING_NOTE, inputs=MAIN_INPUT, outputs=REFRESH_OUTPUT,
        methods=[PREREQUISITES,
                 "Calls shared `refresh()`; SOFA, comorbidity flags and ICU type are already joined by the extended-outcome SQL.",
                 "Core adds first-day SOFA, CHF, CKD and diabetes to age/sex/RAAS with era strata. Class-specific ACEi/ARB indicators are not included.",
                 "Pools ICU labels with fewer than 50 admissions using frequency alone. Evaluates unpenalized and L2-penalized core/ICU fits.",
                 "Additional exploratory fits stratify by era, CHF and exact SOFA; the ICU version also stratifies by pooled ICU type. Rank PH tests and warnings require model-specific interpretation.",
                 "These ICU-entry main sensitivity fits retain ordinary admission-level intervals and live-discharge censoring."],
        results="\n".join(rows) + "\n\nAll rows are exploratory ICU-entry specifications. Their differences do not isolate pre-ICU confounding. Source: [CURRENT_ANALYSIS.json](CURRENT_ANALYSIS.json).",
        related="[05a](05a_patient_cluster_sensitivity_SHORT.md) separately reports cluster intervals for the core model. [05c](05c_time_aligned_severity_SHORT.md) implements the distinct 24-hour landmark; it does not reconstruct pre-ICU severity or independently verify component times.",
        next_step="Optional: [04d — Secondary logistic export](04d_python_logistic_model_SHORT.md). The 05-series supplements do not depend on running 04d.")

    add("04d_python_logistic_model", "04d — Optional secondary Python logistic model",
        objective="Fit and export a secondary binary-outcome logistic model; the primary clinical analysis remains time-to-event Cox modeling.",
        inputs=MAIN_INPUT, outputs=["Coefficient/odds-ratio table plus aggregate manifest under ignored `python/outputs/`.", "No persistent BigQuery table, main survival refresh, or Quarto build."],
        methods=["Calls `load_current_data()` and `fit_secondary_logistic()` directly, not shared `refresh()`.",
                 "Fits statsmodels Logit for in-hospital death using RAAS, age, sex, first-day SOFA, Charlson index, CHF, CKD and diabetes; this is not an era-stratified Cox model.",
                 "First-day information may follow ICU entry. The export is not independent clinical validation or a causal analysis.",
                 "No private CSV input or external analysis-service upload is required."],
        results="See [main reproduction steps](../REPRODUCIBILITY.md) and [validation notes](VALIDATION_NOTES.md) for scope. This guide does not present the optional logistic fit as a primary finding.",
        next_step=next_to("05a_patient_cluster_sensitivity", "05a — Patient-cluster sensitivity"))

    if supplement is not None:
        cohort = supplement["cohort"]
        rows = ["Published clinical results, not the default synthetic notebook output. Source: [selected aggregate record](SURVIVAL_SENSITIVITY_RESULTS.json).", "",
                "| Model | HR | Ordinary 95% CI | Patient-cluster 95% CI | Cluster p |", "| --- | ---: | --- | --- | ---: |"]
        for key, label in [("primary_refined", "Primary age/sex/era"), ("core", "Exploratory SOFA core")]:
            e = supplement["cluster"]["models"][key]
            rows.append(f"| {label} | {e['hr']:.3f} | {interval(e['ordinary'])} | {interval(e['patient_cluster'])} | {pvalue(e['patient_cluster']['p'])} |")
        rows += ["", f"{cohort['n']:,} admissions represent {cohort['patients']:,} patients; {cohort['patients_with_multiple_admissions']:,} patients contributed {cohort['admissions_from_repeat_patients']:,} admissions across repeated hospitalizations."]
        add("05a_patient_cluster_sensitivity", "05a — Patient-cluster sensitivity",
            objective="Compare ordinary and patient-cluster inference on the same primary and exploratory core admissions.",
            inputs=[MODES, "Shares the original extended-outcome/detailed-order inputs; published values come from the selected aggregate record."],
            outputs=SUPP_OUTPUT,
            methods=["Retains point estimates, complete cases, age/sex/era specification and Efron ties; core additionally includes SOFA, CHF, CKD and diabetes.",
                     "Sums Efron score residuals across a patient's admissions, including across era strata. Uses HC0 sandwich variance and normal Wald 95% intervals/p-values without a finite-cluster correction.",
                     "Handles tied event/censor times without jitter; synthetic covariance was compared with R survival. No frailty or recurrent-event process model is fitted.",
                     "Core still uses potentially post-start SOFA. This is a binary-RAAS sensitivity, not a new subgroup contrast."],
            results="\n".join(rows), related=f"[Full published supplementary section]({REPORT}) and [methods/validation guide](SURVIVAL_SENSITIVITY_SUPPLEMENTS.md).",
            next_step=next_to("05b_competing_risks", "05b — Competing hospital endpoints"))

        rows = ["Published clinical results, not the default synthetic output; CIFs are unadjusted and intervals are pointwise 95% intervals.", "",
                "| Qualifying RAAS orders | Day | Death CIF %, 95% CI | Live-discharge CIF %, 95% CI |", "| --- | ---: | --- | --- |"]
        for g in supplement["competing"]["groups"]:
            for row in g["curve"]:
                if row["day"] in [7, 14, 28]:
                    rows.append(f"| {'Yes' if g['raas_order_group'] else 'No'} | {row['day']} | {probability(row, 'death')} | {probability(row, 'discharge')} |")
        difference = supplement["competing"]["death_cif_difference_raas_minus_no_raas"][-1]
        rows += ["", f"Day-28 death-CIF difference, RAAS minus no RAAS: {100*difference['difference']:.2f} percentage points (95% CI {100*difference['lower_95']:.2f} to {100*difference['upper_95']:.2f}). This is an unadjusted association, not a treatment effect."]
        add("05b_competing_risks", "05b — Death and discharge as competing events",
            objective="Report unadjusted cumulative incidence of death and live discharge, alongside separate adjusted cause-specific Cox associations.",
            inputs=[MODES, "Same continuous ICU-entry follow-up; death is event 1 and live discharge event 2."],
            outputs=SUPP_OUTPUT,
            methods=["Uses two-cause Aalen-Johansen probabilities on a fixed daily grid through day 28. Tied endpoints use a shared pre-event risk set without jitter.",
                     "Clinical intervals use 1,000 patient-cluster bootstrap draws, fixed patient ordering and seed 20261118; all admissions/exposure groups of each sampled patient travel together.",
                     "Intervals are pointwise percentile intervals, not simultaneous bands. Original discharge-time proxies for unknown death times are retained.",
                     "Age/sex/era cause-specific Cox models for death and discharge use patient-cluster inference. These adjusted rates and unadjusted CIFs answer different questions; no Fine–Gray model is fitted."],
            results="\n".join(rows), related=f"The [Quarto section]({REPORT}) includes the curves and adjusted cause-specific results. See [the selected aggregate record](SURVIVAL_SENSITIVITY_RESULTS.json).",
            next_step=next_to("05c_time_aligned_severity", "05c — Separate 24-hour landmark"))

        flow = supplement["landmark"]["eligibility"]
        rows = ["Published clinical results, not the default synthetic output.", "",
                f"Excluded {flow['deaths_at_or_before_landmark']:,} deaths and {flow['discharges_at_or_before_landmark']:,} live discharges at or before 24 hours, plus {flow['additional_fallback_deaths_excluded']:,} remaining deaths with unknown death times. Eligible: {flow['eligible_alive_and_hospitalized']:,}; missing core covariates: {flow['eligible_missing_core_covariates']:,}.", "",
                "| Landmark model | Admissions | Deaths | HR | Patient-cluster 95% CI | p |", "| --- | ---: | ---: | ---: | --- | ---: |"]
        for key, label in [("landmark_age_sex", "Age/sex/era"), ("landmark_first_day_sofa_core", "Exploratory SOFA core")]:
            e = supplement["landmark"]["models"][key]
            rows.append(f"| {label} | {e['n']:,} | {e['events']:,} | {e['hr']:.3f} | {interval(e['patient_cluster'])} | {pvalue(e['patient_cluster']['p'])} |")
        add("05c_time_aligned_severity", "05c — Separate 24-hour severity landmark",
            objective="Explore first-day severity among admissions alive and still hospitalized beyond 24 hours after ICU entry; this changes the population and estimand.",
            inputs=[MODES, "Original prescription-order grouping and first-day SOFA/core covariates."],
            outputs=SUPP_OUTPUT,
            methods=["Excludes endpoints at or before 24 hours and remaining deaths with unknown death times, then subtracts one day from eligible follow-up.",
                     "Keeps the original exposure window at or before ICU entry; both landmark models use identical core-complete admissions, era strata and patient-cluster Efron inference.",
                     "Relies on the published first-day-SOFA window. Individual component times and deployed windows were not independently reconstructed.",
                     "SOFA is post-exposure; mediation/selection bias and comorbidity-code timing remain concerns. This does not reconstruct pre-ICU severity or establish causality."],
            results="\n".join(rows), related="[Methods and remaining limitations](SURVIVAL_SENSITIVITY_SUPPLEMENTS.md#05c-a-separate-24-hour-landmark).",
            next_step=f"Read [the published supplementary section]({REPORT}).")

    # Check every companion target before writing any guide.
    for name in notes:
        notebook = name.removesuffix("_SHORT.md") + ".ipynb"
        if not (repo / "notebooks" / notebook).exists():
            raise ValueError("Notebook companion target missing")
    for name, text in notes.items():
        (repo / "docs" / name).write_text(text)
    return sorted(notes)


if __name__ == "__main__":
    names = generate(Path(__file__).resolve().parents[1])
    print(f"Updated {len(names)} SHORT guides from public aggregate records; no analysis execution.")
